package com.hrcoresystem.hrcore_api.modules.tenant.leaves.infrastructure.api;
import com.hrcoresystem.hrcore_api.common.response.ApiResponse; import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service.EmployeeSupervisionScopeService; import com.hrcoresystem.hrcore_api.modules.tenant.leaves.application.dto.LeaveDtos.BalanceResponse; import com.hrcoresystem.hrcore_api.modules.tenant.leaves.application.service.LeaveService; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/me/leave-balances") public class MyLeaveBalanceAliasController {private final LeaveService service;private final EmployeeSupervisionScopeService scope;public MyLeaveBalanceAliasController(LeaveService s,EmployeeSupervisionScopeService c){service=s;scope=c;}@GetMapping @PreAuthorize("hasAuthority('leaves.balances.list')") public ApiResponse<Page<BalanceResponse>> list(@RequestParam(required=false) UUID leaveTypeId,@RequestParam(required=false) Integer year,@PageableDefault(size=25) Pageable page){return ApiResponse.success("Saldos propios consultados correctamente",service.balances(scope.requireCurrentEmployeeId(),leaveTypeId,year,page));}}
